import re
from ..section_generic import TextBasedSectionGeneric
from ..utils.logger import logger


class SectionTgr(TextBasedSectionGeneric):
    """
    Section "tgr" is a part of cus.ini config file.
    Generated content base on ue.yaml.
    Example generated for CLOUD_R4A_CUS:

    [tgr_1]
    ip_addr      = 10.0.2.101
    etgr         = on
    ss_interface = eth101
    side         = SS
    user         = root
    password     = cussim
    update_cmd   = sudo /opt/cus/var/update/update.sh
    restart_cmd  = sudo /etc/init.d/cus-tgr restart
    """
    def __init__(self, subsection_separator='\n\n'):
        super().__init__(subsection_separator)
        self._section_header = '[tgr_{}]'

    def _prepare_section_content(self, ue_config, *args, **kwargs):
        logger.debug("Generating TGR Section")
        for i, key in enumerate(self._get_tgr_keys(ue_config)):
            tgr_ent = ue_config[key]
            subsection_content = [self._section_header.format(str(i + 1))]

            side = "SS" if "ss_interface" in tgr_ent else "MS"
            x_interface = "ss_interface" if "ss_interface" in tgr_ent else "ue_interface"
            dev = tgr_ent[x_interface]

            subsection_content.append(f"ip_addr = {tgr_ent['ip_addr']}")
            subsection_content.append('etgr = on')

            if 'etgr_ip_addr' in tgr_ent:
                subsection_content.append(f"etgr_ip_addr = {tgr_ent['etgr_ip_addr']}")
            if 'ss_ip_addr_pool' in tgr_ent:
                subsection_content.append(f"ss_ip_addr_pool = {tgr_ent['ss_ip_addr_pool']}")

            subsection_content.extend([
                f"{x_interface} = {dev}",
                f"side = {side}",
                'user = root',
                'password = cussim',
                'update_cmd = sudo /opt/cus/var/update/update.sh',
                'restart_cmd = sudo /etc/init.d/cus-tgr restart'
            ])

            self._section_content.append(subsection_content)

    @staticmethod
    def _adjust_printing_style(subsection_content):
        printing_width = max([
            len(line.split('=')[0]) for line in subsection_content
            if '=' in line
        ])

        subsection_content = [
            line.split('=')[0].ljust(printing_width + 3) + '=' + line.split('=')[1]
            if '=' in line else line
            for line in subsection_content
        ]
        return subsection_content

    @staticmethod
    def _add_exit_lines():
        return '\n\n\n'

    @staticmethod
    def _get_tgr_keys(ue_config):
        return sorted(key for key in ue_config if re.search(r'^tgr\d+$', key))
